sources.app.tsx:
// @name Homey remote
// @background #0f172a
// @refresh 60
// A touch remote for a Homey Pro, through its local Web API on your network.
// The cards come from the scene's Cards setting: devices by name, flows,
// whole zones, and "# Name" lines that start a page. Left empty, every
// device shows, a page per zone.
//
// Homey's list of devices (GET /api/manager/devices/device/) holds every
// device with all its capabilities and can be large, so it is read now and
// then (the "Look for new devices every" setting), one device at a time, and
// only what the cards draw is kept (frameos.remember). Between those reads a
// render asks for the devices showing alone (GET .../device/<id>). A tap sets
// a capability (PUT .../device/<id>/capability/<capability> {"value": ...})
// or starts a flow (POST /api/manager/flow/flow/<id>/trigger), and the card
// changes at once.
import {
  Button, Card, Confirm, Header, Icon, SetupScreen, Slider, Switch, Tabs, Value,
  ago, clamp, clockTime, columnsFor, iconName, niceNumber, parseCards, roundRoom, sizesOf, themeOf, words,
} from './ui'
import type { Entry, Look, Page, Sizes, Theme } from './ui'

// A device read less than this long ago is not asked for again.
const FRESH_MS = 5000
// After a tap the card shows what it asked for this long before a read may
// say otherwise (a Z-Wave device can take a moment to report).
const HOLD_MS = 4000

// ---------------------------------------------------------------- talking to Homey

type Homey = { base: string; key: string }

function homeyOf(app): Homey | null {
  let base = String(app.state.homeyAddress || '').trim().replace(/\/+$/, '')
  const key = String(app.state.apiKey || '').trim()
  if (!base || !key) return null
  if (!/^https?:\/\//i.test(base)) base = `http://${base}`
  return { base, key }
}

type Reply = { status: number; data?: any; body?: string; error?: string }

function call(homey: Homey, method: string, path: string, body?: any, raw?: boolean): Reply {
  const reply = frameos.httpRequest(homey.base + path, {
    method,
    headers: { Authorization: `Bearer ${homey.key}`, Accept: 'application/json', 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
    timeoutMs: 10000,
  })
  if (!reply.status) return { status: 0, error: reply.error || 'no answer' }
  if (reply.status >= 400) return { status: reply.status, error: (reply.body || '').slice(0, 120) }
  if (raw) return { status: reply.status, body: reply.body || '' }
  try {
    return { status: reply.status, data: reply.body ? JSON.parse(reply.body) : null }
  } catch (e) {
    return { status: reply.status, data: null }
  }
}

function problemText(homey: Homey, reply: Reply) {
  if (reply.status === 401) return "Homey refused the API key: check the scene's Homey API key setting."
  if (reply.status === 403) return 'The API key may not do this: give it the permission in Homey (Settings, API keys).'
  const error = reply.error || `HTTP ${reply.status}`
  if (error.startsWith('Local network access is off'))
    return `${error}. Turn on Local network access in the frame's settings to reach ${homey.base}.`
  if (!reply.status) return `Could not reach Homey at ${homey.base}: ${error}`
  return `Homey answered ${error}`
}

// Calls fn with the text of each object in a top-level object or array,
// {"id1": {...}, "id2": {...}}, so a long list is parsed one entry at a
// time and never all at once (a big home's device list is hundreds of KB of
// JSON, and parsed whole many times that).
function eachEntry(body: string, fn: (text: string) => void) {
  let depth = 0
  let start = -1
  const length = body.length
  for (let i = 0; i < length; i++) {
    const c = body.charCodeAt(i)
    if (c === 34) {
      // A string: jump to its closing quote, past escaped ones.
      let end = i
      for (;;) {
        end = body.indexOf('"', end + 1)
        if (end < 0) return
        let slashes = 0
        while (body.charCodeAt(end - 1 - slashes) === 92) slashes++
        if (slashes % 2 === 0) break
      }
      i = end
    } else if (c === 123 || c === 91) {
      depth++
      if (depth === 2 && c === 123) start = i
    } else if (c === 125 || c === 93) {
      if (depth === 2 && c === 125 && start >= 0) {
        fn(body.slice(start, i + 1))
        start = -1
      }
      depth--
    }
  }
}

// ---------------------------------------------------------------- devices, kept small

// What a card needs of a capability: its value, unit, title, range, and the
// choices of one with a list of values (a thermostat's modes).
type Cap = { v: any; u?: string; t?: string; min?: number; max?: number; step?: number; d?: number; opts?: { id: string; t: string }[] }
type Device = {
  id: string; n: string; z: string; c: string; ok: boolean; why?: string; caps: Record<string, Cap>
  at: number; hold?: number; err?: string; sent?: number
}

const DRAWN = /^(onoff|dim|light_temperature|target_temperature|thermostat_mode|measure_.+|meter_.+|alarm_.+|windowcoverings_state|windowcoverings_set|volume_set|volume_mute|speaker_playing|speaker_next|speaker_prev|speaker_track|speaker_artist|locked|button|homealarm_state)$/

function slimDevice(device: any, now: number): Device {
  const caps: Record<string, Cap> = {}
  const all = device.capabilitiesObj || {}
  let measures = 0
  for (const id of device.capabilities || Object.keys(all)) {
    const cap = all[id]
    if (!cap || !DRAWN.test(id)) continue
    // A multisensor reports a dozen values; a card has room for a few.
    if (/^(measure|meter)_/.test(id) && ++measures > 5) continue
    const kept: Cap = { v: cap.value ?? null }
    if (cap.units) kept.u = String(cap.units)
    if (cap.title) kept.t = String(cap.title).slice(0, 24)
    if (typeof cap.min === 'number') kept.min = cap.min
    if (typeof cap.max === 'number') kept.max = cap.max
    if (typeof cap.step === 'number') kept.step = cap.step
    if (typeof cap.decimals === 'number') kept.d = cap.decimals
    if (Array.isArray(cap.values))
      kept.opts = cap.values.slice(0, 6).map((each) => ({ id: String(each.id), t: String(each.title || each.id).slice(0, 12) }))
    caps[id] = kept
  }
  const ok = device.available !== false
  const slim: Device = { id: String(device.id), n: String(device.name || ''), z: String(device.zone || ''), c: String(device.class || 'other'), ok, caps, at: now }
  if (!ok && device.unavailableMessage) slim.why = String(device.unavailableMessage).slice(0, 80)
  return slim
}

type Zone = { id: string; n: string; p: string }
type Flow = { id: string; n: string; adv: boolean }
// Everything the remote keeps between renders (frameos.remember).
type Index = { at: number; devices: Device[]; zones: Zone[]; flows: Flow[] | null; flowsAt?: number }

const loadIndex = (): Index | null => (frameos.recall('index') as any) || null
const saveIndex = (index: Index) => frameos.remember('index', index as any)

// Each card reads its device (or its flow's last start), its slider's draft
// and the lock being asked about through signals: a tap runs only the card it
// changed, not get().
const shown: Record<string, any> = {}
const deviceOf = (id: string) => shown[id] || (shown[id] = signal(undefined))
const started: Record<string, any> = {}
const startedOf = (id: string) => started[id] || (started[id] = signal(undefined))
const drafts: Record<string, any> = {}
const draftOf = (id: string) => drafts[id] || (drafts[id] = signal(null))
const asking = signal('')
const setAsking = (id: string) => {
  frameos.remember('asking', id)
  asking.value = id
}

// Reads the whole list of devices (and zones, and flows where cards need
// them). Answers the problem that stopped it, or ''.
function readIndex(homey: Homey, old: Index | null, wantFlows: boolean): { index: Index | null; problem: string } {
  const now = Date.now()
  const zonesReply = call(homey, 'GET', '/api/manager/zones/zone/')
  if (zonesReply.status !== 200) return { index: old, problem: problemText(homey, zonesReply) }
  const zones: Zone[] = []
  for (const key in zonesReply.data || {}) {
    const zone = zonesReply.data[key]
    zones.push({ id: String(zone.id || key), n: String(zone.name || ''), p: String(zone.parent || '') })
  }
  const devicesReply = call(homey, 'GET', '/api/manager/devices/device/', undefined, true)
  if (devicesReply.status !== 200) return { index: old, problem: problemText(homey, devicesReply) }
  const devices: Device[] = []
  eachEntry(devicesReply.body || '', (text) => {
    try {
      devices.push(slimDevice(JSON.parse(text), now))
    } catch (e) {
      // One entry that does not parse costs that device alone.
    }
  })
  devicesReply.body = ''
  devices.sort((a, b) => (a.n < b.n ? -1 : a.n > b.n ? 1 : 0))
  const index: Index = { at: now, devices, zones, flows: old?.flows ?? null, flowsAt: old?.flowsAt }
  if (wantFlows) readFlows(homey, index)
  return { index, problem: '' }
}

// Flows and Advanced Flows, by name; only the ones that can be started.
function readFlows(homey: Homey, index: Index) {
  const flows: Flow[] = []
  for (const [path, adv] of [['/api/manager/flow/flow/', false], ['/api/manager/flow/advancedflow/', true]] as [string, boolean][]) {
    const reply = call(homey, 'GET', path, undefined, true)
    if (reply.status !== 200) continue
    eachEntry(reply.body || '', (text) => {
      // Only the name, id and whether it can be started: a flow's cards
      // can be long, so the fields are read off the text.
      const id = /"id"\s*:\s*"([^"]+)"/.exec(text)
      const name = /"name"\s*:\s*"((?:[^"\\]|\\.)*)"/.exec(text)
      if (!id || !name || /"triggerable"\s*:\s*false/.test(text)) return
      let n = name[1]
      try {
        n = JSON.parse(`"${name[1]}"`)
      } catch (e) {}
      flows.push({ id: id[1], n, adv })
    })
  }
  index.flows = flows
  index.flowsAt = Date.now()
}

// Sets one capability, showing the new value at once.
function setCapability(homey: Homey, id: string, capability: string, value: any, also?: Record<string, any>) {
  const index = loadIndex()
  const device = index?.devices.find((each) => each.id === id)
  if (!index || !device) return
  const reply = call(homey, 'PUT', `/api/manager/devices/device/${id}/capability/${capability}`, { value })
  if (reply.status >= 200 && reply.status < 300) {
    if (device.caps[capability]) device.caps[capability].v = value
    for (const other in also || {}) if (device.caps[other]) device.caps[other].v = also[other]
    device.hold = Date.now() + HOLD_MS
    device.err = ''
    device.sent = Date.now()
  } else {
    device.err = problemText(homey, reply)
    device.at = 0
  }
  saveIndex(index)
  // The card shows it at once. A failed call sets no signal: get() draws it,
  // reading the device again, as it always did.
  if (!device.err) deviceOf(id).value = device
}

function startFlow(homey: Homey, flow: Flow) {
  const reply = call(homey, 'POST', `/api/manager/flow/${flow.adv ? 'advancedflow' : 'flow'}/${flow.id}/trigger`, {})
  const sent = frameos.recall('flowsSent') || {}
  sent[flow.id] = reply.status >= 200 && reply.status < 300 ? { at: Date.now() } : { at: Date.now(), err: problemText(homey, reply) }
  frameos.remember('flowsSent', sent)
  if (!sent[flow.id].err) startedOf(flow.id).value = sent[flow.id]
}

// ---------------------------------------------------------------- the cards' list

type Item = { entry: Entry; device?: Device; flow?: Flow; error?: string }

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const same = (a: string, b: string) => a.trim().toLowerCase() === b.trim().toLowerCase()

// Each line of a page as cards: a device by id, name or Zone/Name, every
// device of a *Zone, or a flow:Name.
function itemsOf(page: Page, index: Index): Item[] {
  const items: Item[] = []
  const zoneName = (id: string) => index.zones.find((zone) => zone.id === id)?.n || ''
  for (const entry of page.entries) {
    const ref = entry.ref
    if (/^flow:/i.test(ref)) {
      const name = ref.slice(5).trim()
      const flow = (index.flows || []).find((each) => same(each.n, name))
      items.push(flow ? { entry, flow } : { entry, error: index.flows ? `No flow called "${name}" that can be started` : 'Loading flows...' })
    } else if (ref.startsWith('*')) {
      const name = ref.slice(1).trim()
      const zone = index.zones.find((each) => same(each.n, name))
      if (!zone) items.push({ entry, error: `No zone called "${name}"` })
      else for (const device of index.devices) if (device.z === zone.id) items.push({ entry: { ref: device.id, name: '', opts: entry.opts }, device })
    } else {
      const slash = ref.lastIndexOf('/')
      const zone = slash > 0 ? ref.slice(0, slash) : ''
      const name = slash > 0 ? ref.slice(slash + 1) : ref
      const device = UUID.test(ref)
        ? index.devices.find((each) => each.id === ref)
        : index.devices.find((each) => same(each.n, name) && (!zone || same(zoneName(each.z), zone)))
      items.push(device ? { entry, device } : { entry, error: `No device called "${ref}"` })
    }
  }
  return items
}

// With no cards listed: every device, a page per zone (zones in Homey's
// order, the ones without devices left out), a big zone over several pages.
function zonePages(index: Index, most: number): Page[] {
  const pages: Page[] = []
  for (const zone of index.zones) {
    const entries = index.devices.filter((device) => device.z === zone.id && Object.keys(device.caps).length > 0)
      .map((device) => ({ ref: device.id, name: '', opts: {} }))
    for (let at = 0; at < entries.length; at += most)
      pages.push({ title: at ? `${zone.n} ${at / most + 1}` : zone.n, entries: entries.slice(at, at + most) })
  }
  return pages
}

// ---------------------------------------------------------------- what each card is

const CLASS_ICONS: Record<string, string> = {
  light: 'bulb', socket: 'plug', thermostat: 'thermostat', heater: 'heater', windowcoverings: 'blinds', blinds: 'blinds',
  curtain: 'blinds', sunshade: 'blinds', awning: 'blinds', garagedoor: 'door', speaker: 'speaker', tv: 'tv', amplifier: 'speaker',
  lock: 'lock', sensor: 'gauge', fan: 'fan', button: 'button', doorbell: 'bell', homealarm: 'shield', vacuumcleaner: 'vacuum',
  airconditioning: 'snowflake', airpurifier: 'fan', camera: 'motion', kettle: 'power', coffeemachine: 'power', remote: 'tv',
  solarpanel: 'sun', battery: 'battery', evcharger: 'bolt', waterheater: 'heater', sprinkler: 'water', other: 'toggle',
}
const MEASURE_ICONS: Record<string, string> = {
  measure_temperature: 'thermostat', measure_humidity: 'droplet', measure_power: 'bolt', meter_power: 'bolt',
  measure_luminance: 'sun', measure_battery: 'battery', alarm_motion: 'motion', alarm_contact: 'door', alarm_water: 'droplet',
  alarm_smoke: 'alert', measure_rain: 'rain', measure_wind_strength: 'wind', measure_co2: 'gauge',
}
// An alarm_ capability's words when it is on and when it is off.
const ALARMS: Record<string, [string, string]> = {
  alarm_contact: ['Open', 'Closed'], alarm_motion: ['Motion', 'No motion'], alarm_water: ['Water!', 'Dry'],
  alarm_smoke: ['Smoke!', 'No smoke'], alarm_co: ['CO!', 'No CO'], alarm_co2: ['CO2!', 'CO2 OK'], alarm_heat: ['Heat!', 'Normal'],
  alarm_fire: ['Fire!', 'No fire'], alarm_tamper: ['Tampered', 'OK'], alarm_battery: ['Battery low', 'Battery OK'],
  alarm_generic: ['Alarm', 'OK'], alarm_night: ['Night', 'Day'],
}
const CALM_ALARMS = ['alarm_motion', 'alarm_contact', 'alarm_night']
const TYPES = ['toggle', 'light', 'climate', 'cover', 'media', 'lock', 'sensor', 'button']

function typeOf(device: Device, asked?: string) {
  const wanted = String(asked || '').toLowerCase()
  if (TYPES.includes(wanted)) return wanted
  const caps = device.caps
  if (caps.target_temperature) return 'climate'
  if (caps.windowcoverings_set || caps.windowcoverings_state) return 'cover'
  if (caps.speaker_playing || caps.volume_set) return 'media'
  if (caps.locked) return 'lock'
  if (caps.onoff) return caps.dim || device.c === 'light' ? 'light' : 'toggle'
  if (caps.button) return 'button'
  return 'sensor'
}

// A capability's value as text: "21.5", "54", "Yes".
function capText(cap: Cap) {
  if (typeof cap.v === 'number') return niceNumber(cap.v, cap.d === 0 ? 0 : undefined)
  if (typeof cap.v === 'boolean') return cap.v ? 'Yes' : 'No'
  return cap.v === null || cap.v === undefined ? '-' : String(cap.v)
}

type Ctx = {
  t: Theme; z: Sizes; fast: boolean; compact: boolean; showUpdated: boolean; confirmLocks: boolean; narrow: boolean
  homey: Homey; zoneName: (id: string) => string
}

// A slider's value while a finger drags it, else the device's.
const draftOr = (id: string, key: string, value: number) => {
  const draft = draftOf(id).value
  return draft && draft.key === key ? draft.v : value
}
const setDraft = (id: string, key: string, v: number) => {
  const was = frameos.recall('draft') as any
  if (was && was.id !== id) draftOf(was.id).value = null
  frameos.remember('draft', { id, key, v })
  draftOf(id).value = { id, key, v }
}
const dropDraft = (id: string) => {
  frameos.remember('draft', null)
  draftOf(id).value = null
}

const FlowCard = memo(({ item, ctx }: { item: Item; ctx: Ctx }) => {
  const { t, z } = ctx
  const now = Date.now()
  const flow = item.flow as Flow
  const sent = startedOf(flow.id).value
  const recent = sent && now - sent.at < 10 * 60000
  const run = () => startFlow(ctx.homey, flow)
  return (
    <Card t={t} z={z} look="normal" compact={ctx.compact} icon={iconName(item.entry.opts.icon) || 'flow'}
      name={item.entry.name || flow.n} sub={recent && !sent.err ? `Started ${ago(sent.at, now)}` : 'Flow'}
      error={recent ? sent.err : ''} onTap={run} right={ctx.compact ? null : <Button t={t} z={z} on={false} icon="play" onClick={run} />} />
  )
})

const DeviceCard = memo(({ item, ctx }: { item: Item; ctx: Ctx }) => {
  const { t, z } = ctx
  const now = Date.now()
  const device: Device = deviceOf((item.device as Device).id).value
  // A tap's value holds a few seconds: on a fast screen, look again then.
  if (ctx.fast && (device.hold || 0) > now) frameos.setNextSleep(HOLD_MS / 1000 + 0.5)
  const entry = item.entry
  const caps = device.caps
  const type = typeOf(device, entry.opts.type)
  const id = device.id
  const name = entry.name || device.n
  const firstMeasure = Object.keys(caps).find((cap) => /^measure_/.test(cap))
  const firstAlarm = Object.keys(caps).find((cap) => /^alarm_/.test(cap) && cap !== 'alarm_battery')
  const sensorIcon = MEASURE_ICONS[firstAlarm || ''] || MEASURE_ICONS[firstMeasure || '']
  const icon = iconName(entry.opts.icon) || (device.c === 'sensor' && sensorIcon) || CLASS_ICONS[device.c] || sensorIcon || 'toggle'
  const base = { t, z, icon, name, compact: ctx.compact, error: device.err }
  if (!device.ok) return <Card {...base} look="gone" sub={device.why || 'Unavailable'} />
  const set = (capability: string, value: any, also?: Record<string, any>) => setCapability(ctx.homey, id, capability, value, also)

  // The values a card mentions under its name: "12 W", "54%", "Open".
  const extras = (skip: string[]) => {
    const parts: string[] = []
    for (const cap in caps) {
      if (skip.includes(cap)) continue
      if (cap === 'measure_battery' && typeof caps[cap].v === 'number') parts.push(`battery ${Math.round(caps[cap].v)}%`)
      else if (/^(measure|meter)_/.test(cap) && caps[cap].v !== null) parts.push(`${capText(caps[cap])}${caps[cap].u ? ` ${caps[cap].u}` : ''}`.replace(' %', '%').replace(' °', '°'))
      else if (/^alarm_/.test(cap) && (caps[cap].v === true || cap === 'alarm_contact')) parts.push(ALARMS[cap]?.[caps[cap].v ? 0 : 1] || caps[cap].t || words(cap.slice(6)))
    }
    return parts.slice(0, 3).join(' · ')
  }
  // An alarm that is a warning (water, smoke, a low battery) turns the card
  // red; motion and an open contact only light it.
  const alarmed = Object.keys(caps).some((cap) => /^alarm_/.test(cap) && !CALM_ALARMS.includes(cap) && caps[cap].v === true)
  const lit = Object.keys(caps).some((cap) => CALM_ALARMS.includes(cap) && cap !== 'alarm_night' && caps[cap].v === true)

  if (type === 'toggle' || type === 'light') {
    const isOn = caps.onoff?.v === true
    const toggle = () => set('onoff', !isOn)
    const dim = caps.dim ? draftOr(id, 'dim', isOn ? Number(caps.dim.v ?? 1) : 0) : null
    const warmth = caps.light_temperature && isOn ? draftOr(id, 'temp', Number(caps.light_temperature.v ?? 0.5)) : null
    const more = extras(['onoff', 'dim', 'light_temperature'])
    let sub = isOn ? 'On' : 'Off'
    if (isOn && dim !== null) sub += ` · ${Math.round(dim * 100)}%`
    if (more) sub += ` · ${more}`
    return (
      <Card {...base} look={alarmed ? 'alert' : isOn || lit ? 'on' : 'off'} sub={sub} onTap={toggle}
        right={ctx.narrow ? null : <Switch t={t} z={z} on={isOn} />}>
        {dim !== null ? (
          <Slider t={t} z={z} on={isOn} value={dim} icon="sun" fast={ctx.fast} label={`Brightness ${Math.round(dim * 100)}%`}
            onDraft={(v) => setDraft(id, 'dim', v)}
            onSet={(v) => {
              dropDraft(id)
              const level = Math.max(0.01, Math.round(v * 100) / 100)
              set('dim', level, { onoff: true })
            }} />
        ) : null}
        {warmth !== null ? (
          // Homey's light_temperature runs from 0, cool, to 1, warm.
          <Slider t={t} z={z} on={isOn} value={1 - warmth} icon="thermostat" fast={ctx.fast}
            label={`${warmth > 0.65 ? 'Warm' : warmth < 0.35 ? 'Cool' : 'Neutral'} white`}
            onDraft={(v) => setDraft(id, 'temp', 1 - v)}
            onSet={(v) => {
              dropDraft(id)
              set('light_temperature', Math.round((1 - v) * 100) / 100)
            }} />
        ) : null}
      </Card>
    )
  }

  if (type === 'climate') {
    const target = caps.target_temperature
    const current = caps.measure_temperature
    const low = target?.min ?? 5
    const high = target?.max ?? 35
    const step = target?.step ?? 0.5
    const value = typeof target?.v === 'number' ? target.v : null
    const mode = caps.thermostat_mode
    const modeName = mode ? mode.opts?.find((each) => each.id === mode.v)?.t || words(String(mode.v ?? '')) : ''
    const heating = mode ? mode.v !== 'off' : value !== null && current && typeof current.v === 'number' ? current.v < value : false
    const nudge = (by: number) => {
      if (value === null) return
      set('target_temperature', Math.round(clamp(value + by, low, high) / step) * step)
    }
    const room = current && typeof current.v === 'number' ? niceNumber(current.v, 1) : '-'
    const more = extras(['measure_temperature', 'target_temperature'])
    let sub = [modeName, value !== null ? `to ${niceNumber(value)}°` : '', more].filter(Boolean).join(' · ')
    if (ctx.narrow) sub = `${room}° · ${sub}`
    return (
      <Card {...base} look={heating ? 'on' : 'normal'} sub={sub} right={ctx.narrow ? null : <Value z={z} text={room} unit="°" />}>
        {value !== null ? (
          <div className={`flex items-center gap-[${z.s(8)}px]`}>
            <Button t={t} z={z} on={heating} icon="minus" onClick={() => nudge(-step)} />
            <div className="flex-1 flex flex-col items-center">
              <span className={`text-[${z.s(24)}px] font-bold leading-none`}>{`${niceNumber(value)}°`}</span>
              <span className={`text-[${z.s(12)}px] ${heating ? t.subOn : t.muted}`}>target</span>
            </div>
            <Button t={t} z={z} on={heating} icon="plus" onClick={() => nudge(step)} />
          </div>
        ) : null}
        {mode?.opts && mode.opts.length > 1 ? (
          <div className={`flex gap-[${z.s(6)}px]`}>
            {mode.opts.slice(0, 4).map((each) => (
              <Button t={t} z={z} on={heating} wide picked={each.id === mode.v} label={each.t} onClick={() => set('thermostat_mode', each.id)} />
            ))}
          </div>
        ) : null}
      </Card>
    )
  }

  if (type === 'cover') {
    // windowcoverings_set runs from 0, closed, to 1, open.
    const position = caps.windowcoverings_set ? draftOr(id, 'set', Number(caps.windowcoverings_set.v ?? 0)) : null
    const state = caps.windowcoverings_state?.v
    const open = position !== null ? position > 0 : state === 'up'
    const sub = [position !== null ? (position <= 0 ? 'Closed' : `Open ${Math.round(position * 100)}%`) : state ? words(String(state)) : '', extras([])].filter(Boolean).join(' · ')
    return (
      <Card {...base} look={open ? 'on' : 'normal'} sub={sub}>
        {caps.windowcoverings_state ? (
          <div className={`flex gap-[${z.s(8)}px]`}>
            <Button t={t} z={z} on={open} wide icon="up" picked={state === 'up'} onClick={() => set('windowcoverings_state', 'up')} />
            <Button t={t} z={z} on={open} wide icon="stop" onClick={() => set('windowcoverings_state', 'idle')} />
            <Button t={t} z={z} on={open} wide icon="down" picked={state === 'down'} onClick={() => set('windowcoverings_state', 'down')} />
          </div>
        ) : null}
        {position !== null ? (
          <Slider t={t} z={z} on={open} value={position} icon="blinds" fast={ctx.fast} label={`Open ${Math.round(position * 100)}%`}
            onDraft={(v) => setDraft(id, 'set', v)}
            onSet={(v) => {
              dropDraft(id)
              set('windowcoverings_set', Math.round(v * 100) / 100)
            }} />
        ) : null}
      </Card>
    )
  }

  if (type === 'media') {
    const playing = caps.speaker_playing?.v === true
    const song = [caps.speaker_track?.v, caps.speaker_artist?.v].filter(Boolean).join(' · ')
    const volume = caps.volume_set ? draftOr(id, 'volume', Number(caps.volume_set.v ?? 0)) : null
    const isOn = caps.onoff ? caps.onoff.v === true : true
    if (!isOn)
      return <Card {...base} look="normal" sub="Off" right={<Button t={t} z={z} on={false} icon="power" onClick={() => set('onoff', true)} />} />
    return (
      <Card {...base} look={playing ? 'on' : 'normal'} sub={song || (caps.speaker_playing ? (playing ? 'Playing' : 'Paused') : 'On')}
        onTap={ctx.compact && caps.speaker_playing ? () => set('speaker_playing', !playing) : undefined}>
        {caps.speaker_playing ? (
          <div className={`flex gap-[${z.s(8)}px]`}>
            {caps.speaker_prev ? <Button t={t} z={z} on={playing} wide icon="prev" onClick={() => set('speaker_prev', true)} /> : null}
            <Button t={t} z={z} on={playing} wide icon={playing ? 'pause' : 'play'} onClick={() => set('speaker_playing', !playing)} />
            {caps.speaker_next ? <Button t={t} z={z} on={playing} wide icon="next" onClick={() => set('speaker_next', true)} /> : null}
          </div>
        ) : null}
        {volume !== null ? (
          <Slider t={t} z={z} on={playing} value={volume} icon="volume" fast={ctx.fast} label={`Volume ${Math.round(volume * 100)}%`}
            onDraft={(v) => setDraft(id, 'volume', v)}
            onSet={(v) => {
              dropDraft(id)
              set('volume_set', Math.round(v * 100) / 100)
            }} />
        ) : null}
      </Card>
    )
  }

  if (type === 'lock') {
    const locked = caps.locked?.v === true
    const action = locked ? 'Unlock' : 'Lock'
    const go = () => {
      setAsking('')
      set('locked', !locked)
    }
    if (asking.value === id)
      return <Confirm t={t} z={z} icon={locked ? 'unlock' : 'lock'} question={`${action} ${name}?`} yes={action}
        onYes={go} onNo={() => setAsking('')} />
    const more = extras(['locked'])
    const ask = () => (ctx.confirmLocks ? setAsking(id) : go())
    return (
      <Card {...base} icon={iconName(entry.opts.icon) || (locked ? 'lock' : 'unlock')} look={alarmed ? 'alert' : locked ? 'normal' : 'on'}
        sub={[locked ? 'Locked' : 'Unlocked', more].filter(Boolean).join(' · ')} onTap={ctx.compact ? ask : undefined}
        right={ctx.compact ? null : <Button t={t} z={z} on={!locked} label={ctx.narrow ? undefined : action} icon={ctx.narrow ? (locked ? 'unlock' : 'lock') : undefined}
          onClick={ask} />} />
    )
  }

  if (type === 'button') {
    const press = () => set('button', true)
    const recent = device.sent && now - device.sent < 10 * 60000
    return <Card {...base} look="normal" sub={recent ? `Pressed ${ago(device.sent as number, now)}` : extras(['button']) || 'Tap to press'}
      onTap={press} right={ctx.compact ? null : <Button t={t} z={z} on={false} icon="play" onClick={press} />} />
  }

  // A sensor: its main value at the right, the others under its name.
  // The main value: a measurement (a battery only when there is nothing
  // else), else what its first alarm says ("Dry", "Closed").
  const measures = Object.keys(caps).filter((cap) => /^(measure|meter)_/.test(cap) && caps[cap].v !== null)
  const main = ['measure_temperature', 'measure_power', 'measure_humidity', 'measure_luminance', 'meter_power']
    .find((cap) => measures.includes(cap)) || (firstAlarm ? '' : measures[0] || '')
  const alarmWords = firstAlarm ? ALARMS[firstAlarm] || ['Alarm', 'OK'] : null
  const more = extras(main ? [main] : firstAlarm ? [firstAlarm] : [])
  const right = main ? <Value z={z} text={capText(caps[main])} unit={caps[main].u} />
    : alarmWords ? <span className={`shrink-0 text-[${z.s(18)}px] font-bold`}>{alarmWords[caps[firstAlarm as string].v ? 0 : 1]}</span> : null
  const look: Look = alarmed ? 'alert' : lit ? 'on' : 'normal'
  return <Card {...base} look={look} sub={more || (main ? caps[main].t : '') || ctx.zoneName(device.z)} right={right} />
})

// ---------------------------------------------------------------- the scene

const pageOf = (count: number) => {
  const page = Number(frameos.recall('page') || 0)
  return count ? ((page % count) + count) % count : 0
}

export function onEvent(app, context) {
  const p = context.payload || {}
  let by = 0
  if (context.event === 'forward') by = 1
  else if (context.event === 'back') by = -1
  else if (context.event === 'keyDown' && !p.ctrl && !p.alt && !p.meta) {
    if (p.key === 'ArrowRight' || p.key === 'PageDown') by = 1
    else if (p.key === 'ArrowLeft' || p.key === 'PageUp') by = -1
  }
  if (!by) return false
  frameos.remember('page', Number(frameos.recall('page') || 0) + by)
  frameos.remember('asking', '')
  return true
}

// On a round panel (only the circle inside the square shows) the cards are
// laid out in the square inside that circle, 12 px in from the rim
// (roundRoom), and a setup screen uses the circle (SetupScreen): both at
// their sizes for 480 px, never smaller, so text stays readable there.
export function get(app, context) {
  if (context?.round !== true) return getIn(app, context, sizesOf(app, context))
  const W = context.imageWidth, H = context.imageHeight
  const side = Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2)
  const k = 1 // the frame's render scale makes it larger on a big panel
  return getIn(app, context, { W: side, H: side, k, s: (px: number) => Math.round(px * k), portrait: false, round: { W, H } })
}

function getIn(app, context, z: Sizes) {
  const t = themeOf(app)
  const homey = homeyOf(app)
  if (!homey)
    return (
      <SetupScreen t={t} z={z} icon="home" title="Connect your Homey"
        intro="This remote talks to a Homey Pro on your network and needs its address and an API key."
        steps={[
          {
            head: 'Make an API key',
            text: 'In the Homey web app (my.homey.app): Settings, API keys, New API key. Let it view and control devices, view zones, and view and start flows.',
          },
          {
            head: 'Fill in this scene\'s settings',
            text: "Homey address: its IP address on your network (Homey app: Settings, General). Homey API key: the key you made.",
            code: 'http://192.168.1.50',
          },
          { head: 'Pick the cards', text: 'Leave Cards empty for every device, a page per zone, or list devices by name, one per line.', code: 'Kitchen/Ceiling light' },
        ]}
        note="On a frame managed by FrameOS Cloud, turn on Local network access in the frame's settings to reach your Homey." />
    )

  const title = String(app.state.title ?? '').trim() || 'Home'
  const listed: Page[] = parseCards(app.state.cards, title)
  const wantFlows = listed.some((page) => page.entries.some((entry) => /^flow:/i.test(entry.ref)))
  const every = Math.max(60, Number(app.state.devicesEvery) || 900) * 1000
  const now = Date.now()

  // The device list: read again when it is due, when the cards name
  // something it does not know (a minute apart at most), or the first time.
  let index = loadIndex()
  let problem = ''
  const stale = !index || now - index.at > every || (index.devices.length === 0 && now - index.at > 60000)
  if (stale) {
    const read = readIndex(homey, index, wantFlows)
    index = read.index
    problem = read.problem
    if (index) saveIndex(index)
  } else if (wantFlows && index && (!index.flows || now - (index.flowsAt || 0) > every)) {
    readFlows(homey, index)
    saveIndex(index)
  }
  if (!index)
    return (
      <SetupScreen t={t} z={z} icon="alert" title="Check the Homey settings" intro={problem}
        steps={[
          { head: 'Check the address', text: "The scene's Homey address setting: the Homey's IP address on your network, from the Homey app (Settings, General).", code: homey.base },
          { head: 'Check the API key', text: 'A key from Settings, API keys in the Homey web app, allowed to view devices and zones.' },
        ]}
        note="On a frame managed by FrameOS Cloud, turn on Local network access in the frame's settings to reach your Homey." />
    )

  const showAll = app.state.allDevices !== false && app.state.allDevices !== 'false'
  // At most this many cards on a page: each is a few hundred elements to lay
  // out, and an ESP32 has a few MB for all of them.
  const most = app.frame.embedded ? 16 : 40
  const pages = listed.length ? listed : showAll ? zonePages(index, most) : []
  if (!pages.length)
    return (
      <SetupScreen t={t} z={z} icon="toggle" title="Add your cards"
        intro={`Connected to ${homey.base}, ${index.devices.length} devices. Now say what to show.`}
        steps={[
          { head: 'One device per line', text: "In this scene's settings, under Cards, by its name in Homey; Zone/Name when two share a name.", code: 'Living room/Ceiling light' },
          { head: 'Flows and zones', text: 'flow:Name is a button that starts a flow; *Zone is every device in that zone.', code: 'flow:Good night' },
          { head: 'Pages', text: 'A line starting with # starts a page, a tab at the top. Swipe in from an edge to turn pages.', code: '# Downstairs' },
        ]} />
    )

  const page = pageOf(pages.length)
  const all = itemsOf(pages[page], index)
  const items = all.slice(0, most)

  // Between reads of the whole list: the devices showing, one by one.
  if (!stale) {
    let changed = false
    for (const item of items) {
      const device = item.device
      if (!device || now - device.at < FRESH_MS || (device.hold && now < device.hold)) continue
      const reply = call(homey, 'GET', `/api/manager/devices/device/${device.id}`)
      if (reply.status === 200 && reply.data) {
        const fresh = slimDevice(reply.data, now)
        const at = index.devices.findIndex((each) => each.id === device.id)
        if (at >= 0) index.devices[at] = fresh
        item.device = fresh
        changed = true
      } else {
        problem = problemText(homey, reply)
        break
      }
    }
    if (changed) saveIndex(index)
  }

  const compact = app.state.compact === true || app.state.compact === 'true'
  const showUpdated = app.state.showUpdated !== false && app.state.showUpdated !== 'false'
  const columns = columnsFor(String(app.state.columns || 'auto'), z, compact)
  const gap = z.s(compact ? 8 : 10)
  const ctx: Ctx = {
    t, z, homey, compact, showUpdated,
    fast: app.frame.fast !== false,
    confirmLocks: app.state.confirmLocks !== false && app.state.confirmLocks !== 'false',
    narrow: (z.W - 2 * z.s(14) - gap * (columns - 1)) / columns < z.s(250),
    zoneName: (id: string) => index?.zones.find((zone) => zone.id === id)?.n || '',
  }
  const draft = (frameos.recall('draft') as any) || null
  const flowsSent = (frameos.recall('flowsSent') || {}) as any
  asking.value = String(frameos.recall('asking') || '')
  for (const item of items) {
    if (item.flow) startedOf(item.flow.id).value = flowsSent[item.flow.id]
    if (!item.device) continue
    deviceOf(item.device.id).value = item.device
    draftOf(item.device.id).value = draft && draft.id === item.device.id ? draft : null
  }
  if (ctx.fast && items.some((item) => (item.device?.hold || 0) > now)) frameos.setNextSleep(HOLD_MS / 1000 + 0.5)

  const newest = Math.max(index.at, ...items.map((item) => item.device?.at || 0))
  const pick = (to: number) => {
    frameos.remember('page', to)
    frameos.remember('asking', '')
  }
  // Refresh reads the whole list again (a device added or renamed in Homey).
  const refresh = () => {
    const kept = loadIndex()
    if (kept) {
      kept.at = 0
      kept.flowsAt = 0
      saveIndex(kept)
    }
  }
  const tabsBelow = app.state.tabs === 'bottom'
  const tabs = <Tabs t={t} z={z} pages={pages} page={page} onPick={pick} />
  return roundRoom(t, z,
    <div className={`flex flex-col w-full h-full gap-[${z.s(10)}px] p-[${z.s(14)}px] ${t.page}`}>
      <Header t={t} z={z} title={title} updated={showUpdated && newest ? `Updated ${clockTime(newest)}` : ''} onRefresh={refresh} />
      {tabsBelow ? null : tabs}
      {problem ? (
        <div className={`flex items-center gap-[${z.s(10)}px] rounded-[${z.s(14)}px] px-[${z.s(12)}px] py-[${z.s(8)}px] ${t.banner}`}>
          <Icon name="alert" size={z.s(22)} />
          <span className={`flex-1 text-[${z.s(14)}px] line-clamp-2`}>{problem}</span>
        </div>
      ) : null}
      <div className="flex-1 min-h-0 overflow-y-auto">
        <div className={`grid grid-cols-${columns} gap-[${gap}px]`}>
          {items.map((item) =>
            item.flow ? <FlowCard item={item} ctx={ctx} />
              : item.device ? <DeviceCard item={item} ctx={ctx} />
              : <Card t={t} z={z} look="gone" compact={compact} icon={iconName(item.entry.opts.icon) || 'alert'} name={item.entry.name || item.entry.ref} error={item.error} />,
          )}
          {all.length > items.length ? (
            <Card t={t} z={z} look="gone" compact={compact} icon="alert" name={`${all.length - items.length} more`}
              sub={`${most} cards fit a page: put the rest on a page of their own (# Name)`} />
          ) : null}
        </div>
      </div>
      {tabsBelow ? tabs : null}
    </div>,
  )
}

