  'robot-happy': 'robot', automation: 'robot', 'water-pump': 'water', sprinkler: 'water', valve: 'water',
}
export const iconName = (name?: string): string => {
  const key = String(name || '').replace(/^mdi:/, '').toLowerCase()
  return PATHS[key] ? key : ALIASES[key] || ''
}

const FILLED: Record<string, boolean> = { play: true, pause: true, next: true, prev: true, stop: true }

export const Icon = ({ name, size }: { name: string; size: number }) => {
  const filled = FILLED[name]
  return (
    <svg className={`w-[${size}px] h-[${size}px] shrink-0`} viewBox="0 0 24 24"
      fill={filled ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth={filled ? 0 : 2}
      strokeLinecap="round" strokeLinejoin="round">
      <path d={PATHS[name] || PATHS.toggle} />
    </svg>
  )
}

// ---------------------------------------------------------------- helpers

export const clamp = (value: number, low: number, high: number) => Math.max(low, Math.min(high, value))

// A number as people read it: at most one decimal, none for big values.
export function niceNumber(value: number, decimals?: number) {
  if (!Number.isFinite(value)) return '-'
  if (decimals !== undefined && decimals >= 0) return value.toFixed(Math.min(decimals, 2))
  const abs = Math.abs(value)
  if (abs >= 100 || Number.isInteger(value)) return String(Math.round(value))
  return value.toFixed(1)
}

export const capitalize = (text: string) => (text ? text.charAt(0).toUpperCase() + text.slice(1) : text)
// "heat_cool" -> "Heat cool", "armed_away" -> "Armed away"
export const words = (text: string) => capitalize(String(text ?? '').replace(/_/g, ' '))

export function clockTime(at: number) {
  const date = new Date(at)
  return `${date.getHours()}:${String(date.getMinutes()).padStart(2, '0')}`
}
// "just now", "5 min ago", "3 h ago", or the time.
export function ago(at: number, now: number) {
  if (!at) return ''
  const minutes = Math.round((now - at) / 60000)
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes} min ago`
  if (minutes < 24 * 60) return `${Math.round(minutes / 60)} h ago`
  return `${Math.round(minutes / 1440)} d ago`
}

// ---------------------------------------------------------------- parts

// A slider. On a fast panel (an LCD) it follows the finger and sends the
// value when the finger lifts; on e-paper a tap sets it (one refresh, one
// request). `draft` is the value while the finger is down, kept by the app.
export function Slider({ t, z, on, value, label, icon, fast, onDraft, onSet }: {
  t: Theme; z: Sizes; on: boolean; value: number; label: string; icon: string; fast: boolean
  onDraft: (fraction: number) => void; onSet: (fraction: number) => void
}) {
  const at = (e) => clamp(e.localX / Math.max(1, e.width), 0, 1)
  const percent = Math.round(clamp(value, 0, 1) * 100)
  const down = fast ? (e) => onDraft(at(e)) : undefined
  const move = fast ? (e) => { if (e.buttons) onDraft(at(e)) } : undefined
  const up = fast ? (e) => onSet(at(e)) : undefined
  const tap = fast ? undefined : (e) => onSet(at(e))
  const text = (
    <div className={`flex items-center gap-[${z.s(8)}px] text-[${z.s(15)}px] font-semibold ${t.overlay ? 'h-full' : ''}`}>
      <Icon name={icon} size={z.s(18)} />
      <span className="flex-1 truncate">{label}</span>
    </div>
  )
  if (!t.overlay)
    return (
      <div className={`flex flex-col gap-[${z.s(4)}px]`} onPointerDown={down} onPointerMove={move} onPointerUp={up} onClick={tap}>
        {text}
        <div className={`h-[${z.s(20)}px] rounded-full ${on ? t.trackOn : t.track}`}>
          <div className={`h-full w-[${percent}%] rounded-full ${on ? t.fillOn : t.fill}`} />
        </div>
      </div>
    )
  return (
    <div className={`relative h-[${z.s(40)}px] rounded-full ${on ? t.trackOn : t.track}`}
      onPointerDown={down} onPointerMove={move} onPointerUp={up} onClick={tap}>
      <div className={`h-full w-[${percent}%] rounded-full ${on ? t.fillOn : t.fill}`} />
      <div className={`absolute inset-0 px-[${z.s(12)}px]`}>{text}</div>
    </div>
  )
}

// A round or wide button with an icon and/or a label.
export function Button({ t, z, on, icon, label, picked, wide, onClick }: {
  t: Theme; z: Sizes; on: boolean; icon?: string; label?: string; picked?: boolean; wide?: boolean; onClick: () => void
}) {
  const look = picked ? (on ? t.pickedOn : t.picked) : on ? t.buttonOn : t.button
  return (
    <div className={`${wide ? 'flex-1' : ''} min-w-0 h-[${z.s(44)}px] ${label ? `px-[${z.s(wide ? 4 : 10)}px]` : wide ? '' : `w-[${z.s(44)}px]`} rounded-full flex items-center justify-center gap-[${z.s(6)}px] text-[${z.s(15)}px] font-semibold ${look}`}
      onClick={onClick}>
      {icon ? <Icon name={icon} size={z.s(20)} /> : null}
      {label ? <span className="truncate">{label}</span> : null}
    </div>
  )
}

// The on/off switch drawn at a card's right.
export const Switch = ({ t, z, on }: { t: Theme; z: Sizes; on: boolean }) => (
  <div className={`flex items-center shrink-0 w-[${z.s(52)}px] h-[${z.s(30)}px] px-[${z.s(4)}px] rounded-full ${on ? t.switchOn : t.switchOff}`}>
    <div className={`w-[${z.s(20)}px] h-[${z.s(20)}px] rounded-full ${on ? t.knob : t.knobOff}`} />
  </div>
)

export type Look = 'on' | 'off' | 'alert' | 'normal' | 'gone'

// A card: an icon, the name and a line under it, something at the right (a
// switch, a big value), and the card's controls under that. A tap on the top
// row runs onTap (a toggle, say).
export function Card({ t, z, look, icon, name, sub, right, error, compact, onTap, children }: {
  t: Theme; z: Sizes; look: Look; icon: string; name: string; sub?: string; right?: any; error?: string
  compact?: boolean; onTap?: () => void; children?: any
}) {
  const on = look === 'on' || look === 'alert'
  const shell = look === 'on' ? t.cardOn : look === 'alert' ? t.cardAlert : look === 'gone' ? t.cardOff : t.card
  const bubble = look === 'on' ? t.bubbleOn : look === 'alert' ? t.bubbleAlert : t.bubble
  const bubbleSize = z.s(compact ? 34 : 42)
  return (
    <div className={`flex flex-col gap-[${z.s(10)}px] rounded-[${z.s(18)}px] p-[${z.s(compact ? 10 : 12)}px] ${shell}`}>
      <div className={`flex items-center gap-[${z.s(10)}px] min-h-[${z.s(44)}px]`} onClick={onTap}>
        <div className={`w-[${bubbleSize}px] h-[${bubbleSize}px] shrink-0 rounded-full flex items-center justify-center ${bubble}`}>
          <Icon name={icon} size={z.s(compact ? 18 : 22)} />
        </div>
        <div className="flex-1 min-w-0 flex flex-col">
          <span className={`text-[${z.s(compact ? 15 : 17)}px] font-semibold truncate`}>{name}</span>
          {error ? (
            <span className={`text-[${z.s(13)}px] line-clamp-2 ${on ? t.errorOn : t.error}`}>{error}</span>
          ) : sub ? (
            <span className={`text-[${z.s(13)}px] truncate ${on ? t.subOn : t.muted}`}>{sub}</span>
          ) : null}
        </div>
        {right}
      </div>
      {compact ? null : children}
    </div>
  )
}

// A big value at a card's right: "21.5" and its unit.
export const Value = ({ z, text, unit }: { z: Sizes; text: string; unit?: string }) => {
  // A degree sign belongs to the number; other units sit small after it.
  const joined = unit === '°' || unit === '°C' || unit === '°F'
  return (
    <div className="flex items-end shrink-0">
      <span className={`text-[${z.s(26)}px] font-bold leading-none`}>{joined ? `${text}°` : text}</span>
      {unit && !joined ? <span className={`text-[${z.s(14)}px] ml-[${z.s(3)}px] pb-[${z.s(2)}px]`}>{unit}</span> : null}
      {unit && joined && unit !== '°' ? <span className={`text-[${z.s(14)}px] pb-[${z.s(2)}px]`}>{unit.slice(1)}</span> : null}
    </div>
  )
}

// The page tabs. Scrolls sideways when there are more than fit.
export function Tabs({ t, z, pages, page, onPick }: { t: Theme; z: Sizes; pages: Page[]; page: number; onPick: (index: number) => void }) {
  if (pages.length < 2) return null
  return (
    <div className="overflow-x-auto shrink-0">
      <div className={`flex gap-[${z.s(8)}px]`}>
        {pages.map((each, index) => (
          <div className={`shrink-0 h-[${z.s(44)}px] px-[${z.s(18)}px] rounded-full flex items-center text-[${z.s(16)}px] font-semibold whitespace-nowrap ${index === page ? t.tabOn : t.tab}`}
            onClick={() => onPick(index)}>
            {each.title}
          </div>
        ))}
      </div>
    </div>
  )
}

// The top bar: the title, when it was updated, and a button to fetch again.
export function Header({ t, z, title, updated, onRefresh }: { t: Theme; z: Sizes; title: string; updated: string; onRefresh: () => void }) {
  return (
    <div className="flex items-center gap-[12px] shrink-0">
      <span className={`flex-1 min-w-0 truncate text-[${z.s(28)}px] font-bold`}>{title}</span>
      {updated ? <span className={`text-[${z.s(14)}px] ${t.muted}`}>{updated}</span> : null}
      <div className={`w-[${z.s(44)}px] h-[${z.s(44)}px] rounded-full flex items-center justify-center ${t.button}`} onClick={onRefresh}>
        <Icon name="refresh" size={z.s(20)} />
      </div>
    </div>
  )
}

// A screen that says what to set up, step by step.
export function SetupScreen({ t, z, icon, title, intro, steps, note }: {
  t: Theme; z: Sizes; icon: string; title: string; intro: string; steps: { head: string; text: string; code?: string }[]; note?: string
}) {
  if (z.round) return <RoundSetupScreen t={t} z={z} icon={icon} title={title} intro={intro} steps={steps} note={note} />
  return (
    <div className={`flex flex-col w-full h-full gap-[${z.s(12)}px] p-[${z.s(20)}px] ${t.page}`}>
      <div className={`flex items-center gap-[${z.s(12)}px]`}>
        <div className={`w-[${z.s(48)}px] h-[${z.s(48)}px] shrink-0 rounded-full flex items-center justify-center ${t.bubble}`}>
          <Icon name={icon} size={z.s(26)} />
        </div>
        <div className="flex-1 min-w-0 flex flex-col">
          <span className={`text-[${z.s(26)}px] font-bold leading-tight`}>{title}</span>
          <span className={`text-[${z.s(15)}px] ${t.muted}`}>{intro}</span>
        </div>
      </div>
      <div className="flex-1 min-h-0 overflow-y-auto">
        <div className={`flex flex-col gap-[${z.s(10)}px]`}>
          {steps.map((step, index) => (
            <div className={`flex gap-[${z.s(12)}px] rounded-[${z.s(14)}px] p-[${z.s(12)}px] ${t.card}`}>
              <div className={`w-[${z.s(30)}px] h-[${z.s(30)}px] shrink-0 rounded-full flex items-center justify-center text-[${z.s(16)}px] font-bold ${t.step}`}>
                {index + 1}
              </div>
              <div className="flex-1 min-w-0 flex flex-col gap-[4px]">
                <span className={`text-[${z.s(17)}px] font-semibold`}>{step.head}</span>
                <span className={`text-[${z.s(14)}px] ${t.muted}`}>{step.text}</span>
                {step.code ? (
                  <span className={`self-start rounded-[8px] px-[${z.s(8)}px] py-[2px] font-mono text-[${z.s(13)}px] ${t.code}`}>{step.code}</span>
                ) : null}
              </div>
            </div>
          ))}
        </div>
      </div>
      {note ? <span className={`text-[${z.s(13)}px] ${t.muted}`}>{note}</span> : null}
    </div>
  )
}

// The same on a round panel: the icon and the title in the cap at the top,
// the rest below them in a box as wide as the circle, scrolling, with its
// scroll bar along the rim.
function RoundSetupScreen({ t, z, icon, title, intro, steps, note }: {
  t: Theme; z: Sizes; icon: string; title: string; intro: string; steps?: { head: string; text: string; code?: string }[]; note?: string
}) {
  const { W, H } = z.round!
  const r = Math.min(W, H) / 2
  const top = Math.round(H / 2 - r * 0.42)
  const bottom = Math.round(H / 2 + r * 0.66)
  // As wide as the circle is at the box's top and bottom, 12 px in.
  const w = Math.floor(2 * Math.sqrt((r - 12) ** 2 - (r * 0.66) ** 2))
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-0 top-[${Math.round(H / 2 - r * 0.84)}px] w-[${W}px] h-[${Math.round(r * 0.4)}px] flex flex-col items-center justify-end gap-[${z.s(6)}px]`}>
        <div className={`w-[${z.s(40)}px] h-[${z.s(40)}px] shrink-0 rounded-full flex items-center justify-center ${t.bubble}`}>
          <Icon name={icon} size={z.s(22)} />
        </div>
        <span className={`w-[${Math.round(r * 1.3)}px] text-center text-[${z.s(21)}px] font-bold leading-tight`}>{title}</span>
      </div>
      <div className={`absolute left-[${Math.round((W - w) / 2)}px] top-[${top}px] w-[${w}px] h-[${bottom - top}px] overflow-y-auto`}>
        <div className={`flex flex-col gap-[${z.s(10)}px] pb-[${z.s(12)}px]`}>
          <span className={`text-center text-[${z.s(15)}px] ${t.muted}`}>{intro}</span>
          {(steps || []).map((step, index) => (
            <div className={`flex gap-[${z.s(10)}px] rounded-[${z.s(14)}px] p-[${z.s(10)}px] ${t.card}`}>
              <div className={`w-[${z.s(28)}px] h-[${z.s(28)}px] shrink-0 rounded-full flex items-center justify-center text-[${z.s(15)}px] font-bold ${t.step}`}>
                {index + 1}
              </div>
              <div className="flex-1 min-w-0 flex flex-col gap-[4px]">
                <span className={`text-[${z.s(16)}px] font-semibold`}>{step.head}</span>
                <span className={`text-[${z.s(14)}px] ${t.muted}`}>{step.text}</span>
                {step.code ? (
                  <span className={`self-start rounded-[8px] px-[${z.s(8)}px] py-[2px] font-mono text-[${z.s(14)}px] ${t.code}`}>{step.code}</span>
                ) : null}
              </div>
            </div>
          ))}
          {note ? <span className={`text-[${z.s(14)}px] ${t.muted}`}>{note}</span> : null}
        </div>
      </div>
    </div>
  )
}

// A card asking "are you sure?" in place of the card (a lock, say).
export function Confirm({ t, z, icon, question, yes, onYes, onNo }: {
  t: Theme; z: Sizes; icon: string; question: string; yes: string; onYes: () => void; onNo: () => void
}) {
  return (
    <div className={`flex flex-col gap-[${z.s(10)}px] rounded-[${z.s(18)}px] p-[${z.s(12)}px] ${t.card}`}>
      <div className={`flex items-center gap-[${z.s(10)}px] min-h-[${z.s(44)}px]`}>
        <Icon name={icon} size={z.s(24)} />
        <span className={`flex-1 text-[${z.s(17)}px] font-semibold`}>{question}</span>
      </div>
      <div className={`flex gap-[${z.s(8)}px]`}>
        <Button t={t} z={z} on={false} label="Cancel" wide onClick={onNo} />
        <div className={`flex-1 h-[${z.s(44)}px] rounded-full flex items-center justify-center text-[${z.s(15)}px] font-bold ${t.primary}`} onClick={onYes}>
          {yes}
        </div>
      </div>
    </div>
  )
}
